contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        require(tos.length <= 1);
        bool reverted;
        bool ok;
        if (tos.length == 0) {
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
            assert(reverted);
        } else {
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
            assert(!reverted && ok);
        }
    }
    receive() external payable {}
}

