contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, uint v) public payable {
        require(address(this).balance == 0);
        address[] memory tos = new address[](1);
        tos[0] = address(uint160(12345));
        bool reverted;
        bool ok;
        // this contract's fallback reverts for the transferFrom selector
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        assert(reverted && !ok);
    }
    fallback() external payable {
        if (msg.sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            revert();
        }
    }
    receive() external payable {}
}

